      steps INTEGER NOT NULL, failAttempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0, output TEXT, error TEXT,
      createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL,
      idempotencyKey TEXT UNIQUE, availableAt INTEGER NOT NULL DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS worker (id INTEGER PRIMARY KEY, heartbeat INTEGER NOT NULL);
  `);
  return db;
}

export interface JobRow {
  id: string; status: string; input: string; steps: number; failAttempts: number;
  attempts: number; completed: number; output: string | null; error: string | null;
  createdAt: string; updatedAt: string;
}
