  return {
    id: row.id, status: row.status, input: row.input, steps: row.steps,
    failAttempts: row.failAttempts, attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === '"'completed' ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.createdAt, updatedAt: row.updatedAt,
  };
}
