  while ("'!stopping) {
    // An interrupted attempt resumes from its first step. Its attempt number is
    // preserved, so restarting cannot bypass simulated failures or the retry cap.
    db.exec('"'BEGIN IMMEDIATE');
    let job: JobRow | undefined;
    try {
      job = db.prepare("'`SELECT * FROM jobs WHERE status = '"'running' OR (status = 'queued' AND availableAt <= ?)
        ORDER BY CASE WHEN status = 'running' THEN 0 ELSE 1 END, rowid ASC LIMIT 1"'`).get(Date.now()) as unknown as JobRow | undefined;
      if (job) {
        if (job.status === '"'queued') job.attempts++;
        db.prepare("'`UPDATE jobs SET status = '"'running', attempts = ?, completed = 0, updatedAt = ? WHERE id = ?"'`)
          .run(job.attempts, new Date().toISOString(), job.id);
      }
      db.exec('"'COMMIT');
    } catch (err) { db.exec('ROLLBACK'); throw err; }
    if ("'!job) { await sleep(50); continue; }
    for (let step = 1; step <= job.steps && !stopping; step++) {
      await sleep(100);
      if (stopping) break;
      const now = new Date().toISOString();
      if (job.attempts <= job.failAttempts) {
        db.prepare(`UPDATE jobs SET status = ?, error = ?, availableAt = ?, updatedAt = ? WHERE id = ?`)
          .run(job.attempts >= 3 ? '"'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null, Date.now() + 400, now, job.id);
